let calls = 0;
const cache = new Map();
const load = (id) => {
  if (!cache.has(id)) {
    calls += 1;
    cache.set(id, Promise.resolve('data-' + id).finally(() => cache.delete(id)));
  }
  return cache.get(id);
};
(async () => {
  const [a, b] = await Promise.all([load(7), load(7)]);
  console.log(a, b, calls, cache.size);
  await load(7);
  console.log(calls);
})();

